#include <iostream>
#include <string>

class Person {
public:
    Person(const std::string& n) : name_(n) {}
    // Const member function returning the person's name
    std::string name() const {
        return name_;
    }
private:
    std::string name_;
};

int main() {
    Person p("Alice");
    const Person cp("Bob");
    std::cout << "Name: " << p.name() << std::endl;
    std::cout << "Const Name: " << cp.name() << std::endl;
    return 0;
}
